contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function driving the test
    // params:
    // amt - the deposit amount to call Put with (may be < MinSum)
    // unlock - the unlockTime argument passed to Put
    function run(uint amt, uint unlock) public {
        // precondition: this test needs enough ETH to send
        require(address(this).balance >= amt);

        // ensure caller has no prior deposits recorded: read Acc(msg.sender).balance
        // we use address(this) as the caller when sending value
        // first, assert the initial recorded balance is zero to target the distinguishing case
        require(c.Acc(address(this)).balance == 0);

        // perform the deposit call that is accepted by original P for any msg.value
        c.Put{value: amt}(unlock);

        // observe that after Put the recorded balance increased by exactly amt
        // This is the single assert (violated by M when amt < MinSum because M would revert)
        assert(c.Acc(address(this)).balance == amt);
    }

    // allow this test contract to receive ETH so it can forward deposits
    receive() external payable {}
}

