pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: actor address and an unlockTime candidate provided by the fuzzer
    function testFuzz_property(address actor, uint256 fuzzUnlock) public {
        // Keep actor non-zero
        vm.assume(actor != address(0));
        // Give actor some ETH to call Put with
        uint256 sendVal = 1 ether;
        vm.deal(actor, sendVal);

        // Warp time to a known baseline to make block.timestamp meaningful
        uint256 base = 1 days;
        vm.warp(base);

        // Actor calls Put with fuzzed unlock time and some value
        vm.prank(actor);
        // use low-level call pattern to capture possible revert/success, but Put shouldn't revert for valid funds
        bool ok;
        try c.Put{value: sendVal}(fuzzUnlock) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded, the invariant for the reference contract is:
        // c.Acc(actor).unlockTime >= block.timestamp
        // We read the public mapping getter Acc(actor).unlockTime via the auto-generated getter.
        // If the call reverted, the state wasn't changed; still the invariant holds trivially (unchanged value >= block.timestamp may or may not hold),
        // but we only assert when the call succeeded to observe the post-state.
        if (ok) {
            // single assertion: reference contract must have stored unlockTime >= current block.timestamp
            // This assertion is true for the reference implementation for all inputs, and the mutant which assigns acc.unlockTime = _unlockTime
            // can violate it when fuzzUnlock < block.timestamp, causing this assert to fail on the buggy version for some inputs.
            (uint256 storedUnlock,,,,) = _readAccTuple(actor);
            assertTrue(storedUnlock >= block.timestamp);
        }
    }

    // Helper to read the public struct mapping via its auto-generated getter.
    // The compiler created: function Acc(address) public view returns (uint unlockTime, uint balance)
    // But solidity older/newer sometimes returns a single tuple; to be robust, call the getter and destructure manually via low-level staticcall.
    function _readAccTuple(address actor) internal view returns (uint256 unlockTime, uint256 balance, address dummy1, uint256 dummy2, uint256 dummy3) {
        // Directly call the public getter
        (uint256 u, uint256 b) = c.Acc(actor);
        return (u, b, address(0), 0, 0);
    }
}

