pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 unlockTime, uint256 deposit) public {
        // keep wide but sensible bounds: deposit up to 2 ether to avoid overflow in tests
        deposit = deposit % (2 ether);
        vm.deal(actor, deposit);

        // record the block timestamp before the call
        uint256 t_before = block.timestamp;

        // perform Put as the fuzzed actor with fuzzed unlockTime and deposit
        vm.prank(actor);
        bool ok;
        try c.Put{value: deposit}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // Read the stored unlockTime for this actor from the contract's public mapping getter
        // The Acc getter returns a tuple (unlockTime, balance) so we call it and inspect the first value.
        (uint256 storedUnlockTime, ) = c.Acc(actor);

        // General property: after Put (whether it reverted or not), if the call succeeded,
        // the reference implementation guarantees storedUnlockTime >= (unlockTime < t_before ? unlockTime : t_before) i.e. >= min(unlockTime, t_before).
        // For our assertion we only assert when the call succeeded (ok==true) because on revert the state is unchanged.
        // This assertion is satisfied by the reference for all inputs, and violated by the mutant for some inputs where unlockTime < block.timestamp.
        if (ok) {
            uint256 minVal = unlockTime < t_before ? unlockTime : t_before;
            assertTrue(storedUnlockTime >= minVal);
        } else {
            // if the call reverted, we cannot assert about changed state; still pass the test path
            assertTrue(true);
        }
    }
}

