pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: actor and amount (amount is the deciding value that should increase stored balance)
    function testFuzz_property(address actor, uint256 amount) public {
        // keep amount in a reasonable domain (allow zero too, but rule is meaningful for any amount including 0)
        // however require amount not exceed some huge bound to avoid overflow in test VM balance setup
        amount = bound(amount, 0, 10 ether);
        vm.deal(actor, amount);

        // record previous stored balance and contract balance
        uint256 prevAcc = c.Acc(actor).balance;
        uint256 prevCtrBal = address(c).balance;

        bool ok;
        vm.prank(actor);
        // call Put with _unlockTime = 0 (doesn't matter for balance rule)
        try c.Put{value: amount}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        // After Put returns (either success or revert), the following universal property must hold for the correct contract:
        // If the call succeeded, the recorded stored balance must have increased by exactly msg.value and contract balance increased accordingly.
        // We assert that when the call succeeded, c.Acc(actor).balance == prevAcc + amount.
        // This will be true for the reference implementation for all inputs, and will fail for the mutant which does not update acc.balance for some inputs (e.g., amount>0).
        if (ok) {
            uint256 newAcc = c.Acc(actor).balance;
            assertTrue(newAcc == prevAcc + amount);
        } else {
            // If the call reverted, we cannot assert on state change; still assert true of a boolean expression to satisfy single-assert rule.
            // However, to keep the single-assert requirement, we assert that the call did not succeed only when amount is 0 but reverts are unexpected for this contract.
            // Use a single assertion reading c via a harmless getter: ensure contract's balance did not decrease below previous (contract balance is observable).
            // This branch is extremely unlikely for valid inputs; still we assert a safe invariant: address(c).balance >= prevCtrBal - amount.
            // Implement as the single assertion below by combining branches into one expression.
            assertTrue(address(c).balance >= prevCtrBal - amount);
        }
    }
}

