pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: actor address and deposit amount and unlock time
    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        // keep amount in a reasonable, wide domain but non-zero so a deposit occurs
        amount = bound(amount, 1, 1 ether * 1000);
        // actor should not be zero address to be a realistic caller
        vm.assume(actor != address(0));

        // fund the actor and perform the deposit as that actor
        vm.deal(actor, amount);
        // capture previous stored balance for actor
        uint256 prevAcc = c.Acc(actor); // uses public getter; returns Holder.balance (auto-generated returns second tuple element)
        // note: the public mapping getter for a struct returns the fields; in solidity it'll return (unlockTime, balance)
        // but accessing c.Acc(actor) yields a tuple; to read balance we rely on tuple-to-single conversion via uint256 prevAcc = c.Acc(actor);
        // to be compatible, we instead call and destructure explicitly
        // however we must keep to single assertion and this setup — adjust by doing explicit call above

        // Actually destructure the tuple by calling the getter that returns both fields
        (uint256 prevUnlock, uint256 prevBalance) = c.Acc(actor);

        // do the deposit
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // read stored balance after the deposit
        (uint256 afterUnlock, uint256 afterBalance) = c.Acc(actor);

        // The general invariant (single assertion): the stored balance increases by exactly msg.value
        // i.e., afterBalance == prevBalance + amount
        assertTrue(afterBalance == prevBalance + amount);
    }
