pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor and amount; the difference is about recording acc.balance vs contract balance
    function testFuzz_property(address actor, uint256 amt) public {
        // admissible domain: nonzero positive deposit and avoid uint overflow in stored balance
        vm.assume(amt > 0);
        // ensure actor has funds to send
        vm.deal(actor, amt);

        // read previous stored per-address balance
        uint256 prevAcc = c.Acc(actor).balance;
        // avoid overflow in the invariant: require prevAcc + amt doesn't wrap
        vm.assume(prevAcc + amt >= prevAcc);

        // perform the deposit from 'actor' calling Put with an arbitrary unlock time (use block.timestamp)
        vm.prank(actor);
        c.Put{value: amt}(block.timestamp + 1);

        // After a successful Put on the reference contract:
        // 1) the contract's ETH balance increases by amt
        // 2) the public Acc(actor).balance reflects the increase (prevAcc + amt)
        // We check both via single assert: assertTrue over conjunction
        uint256 balAfter = address(c).balance;
        uint256 accAfter = c.Acc(actor).balance;

        // Compose the property: contract balance increased and stored per-account balance equals prevAcc + amt
        assertTrue(balAfter >= amt && accAfter == prevAcc + amt);
    }
}

